INSERT INTO `it_survey_checklist_items` VALUES (1,1,'Is the POS touch screen clean, responsive, and free from cracks or physical damage?',NULL,1,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(2,1,'Does the cash drawer open automatically and smoothly on cash invoice printing?',NULL,2,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(3,1,'Are all power and peripheral cables neatly routed, secured, and undamaged?',NULL,3,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(4,1,'Is the barcode scanner responsive and reading product barcodes without delay?',NULL,4,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(5,2,'Does the thermal receipt printer produce clean, legible prints without fading?',NULL,1,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(6,2,'Does the automatic paper cutter work smoothly without jamming?',NULL,2,1,'2026-11-13 18:16:00','2026-11-13 18:16:00'),(7,2,'Is the network/USB cable securely attached to the printer?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(8,2,'Is there adequate thermal receipt paper stock stored near the station?',NULL,4,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(9,3,'Are all Ethernet patch cables properly labeled and plugged into the switch/router?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(10,3,'Is the primary Internet connection stable and responding with low ping latency?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(11,3,'Are branch Wi-Fi access points powered and broadcasting properly?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(12,3,'Is the network rack/enclosure locked, ventilated, and free of dust build-up?',NULL,4,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(13,4,'Is the UPS functioning properly on mains power without error beeps or fault lights?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(14,4,'Does the UPS hold the POS system during simulated power failover?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(15,4,'Are all UPS power cables and surge protectors firmly connected?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(16,5,'Are all branch security cameras online with clean, unobstructed lenses?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(17,5,'Is the DVR/NVR actively recording and storing history as per company policy?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(18,5,'Is the CCTV live monitoring screen working and showing all camera feeds?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(19,6,'Is CNET ERP running the approved standard version across all terminals?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(20,6,'Are offline transactions syncing properly with the central server?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(21,6,'Can cashiers login without database connection timeouts?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(22,7,'Is the SQL Server service running smoothly without memory or disk exhaustion?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(23,7,'Was yesterday\'s automated daily database backup created and verified?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(24,7,'Are transaction log files within acceptable size limits?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(25,8,'Did the daily fiscal closing and Z-Report print successfully at end of day?',NULL,1,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(26,8,'Are fiscal memory and EJ (Electronic Journal) storage within valid limits?',NULL,2,1,'2026-11-13 18:16:01','2026-11-13 18:16:01'),(27,8,'Is the fiscal printer driver communicating without serial port errors?',NULL,3,1,'2026-11-13 18:16:01','2026-11-13 18:16:01');
