INSERT INTO `question_surveys` VALUES (1,'Bole Medhanialem','04','በሳምንት 1–2 ጊዜ','ቡና/መጠጥ',NULL,'150–250 ብር','[\"ትኩስ ቡና\",\"ጣፋጭ\\/ዴዘርት\"]',NULL,'አዎ','ኦት ሚልክ (Oat milk) አማራጭ ቢጨመርበት ጥሩ ነው','[\"የምርት ጥራት\",\"ምቾት\",\"የብራንዱ ስም\"]',NULL,'በጣም ጥሩ','ተመጣጣኝ','[\"የአገልግሎት ፍጥነት\",\"የመኪና ማቆሚያ\"]',NULL,'አይ',NULL,NULL,'ወደ ሌላ የካልዲስ ቅርንጫፍ እሄዳለሁ',NULL,'በጣም ጠቃሚ','በጣም ጥሩ','[\"ፈጣን አገልግሎት\"]',NULL,'በጣም ጥሩ','[\"የመቀመጫ ምቾት\"]',NULL,'አዎ አዳዲስ የቁርስና የቡና አማራጮችን ቢመክሩን በጣም ይጠቅማል።','የጠረጴዛ አገልግሎት ፍጥነት በጠዋት ሰዓት ቢሻሻል መልካም ነው።','ጥሩ የቡና ጥራት እና ምቹ የመቀመጫ ድባብ ሁሌም እንድመጣ ያደርገኛል።',NULL,NULL,'2026-09-25 14:39:41'),(2,'Kazanchis','12','በሳምንት 3 ጊዜ ወይም ከዚያ በላይ','ስብሰባ/ስራ',NULL,'351–500 ብር','[\"ትኩስ ቡና\",\"ምሳ\",\"ቀዝቃዛ መጠጦች\"]',NULL,'የለም',NULL,'[\"አካባቢ\\/ቦታ\",\"አገልግሎት\",\"የቦታው አየር\\/አቀማመጥ\"]',NULL,'ጥሩ','መካከለኛ/ተገቢ','[\"የሰራተኞች አገልግሎት\",\"ንጽህና\"]',NULL,'አዎ','የተሻለ አገልግሎት',NULL,'ወደ ሌላ ካፌ/የቡና ቤት እሄዳለሁ',NULL,'ጠቃሚ','ጥሩ','[\"የተሻለ ግንኙነት\",\"የሜኑ ማብራሪያ\"]',NULL,'ጥሩ','[\"የጠረጴዛና ወንበር አቀማመጥ\",\"ሙዚቃ\\/ድባብ\"]',NULL,'በጣም ይጠቅማል፣ በተለይ ፈጣን ምግቦችና ስፔሻል ቡናዎች ሲኖሩ።','የዋይፋይ ፍጥነት እና የላፕቶፕ ቻርጀር ሶኬቶች ቢበዙ።','ፈጣን አገልግሎት እና ጸጥ ያለ የስራ ድባብ።',NULL,NULL,'2026-09-25 14:39:41'),(3,'Sarbet','02','አልፎ አልፎ','ከጓደኞች ጋር ለመገናኘት',NULL,'251–350 ብር','[\"ፍራፔ\",\"ጣፋጭ\\/ዴዘርት\"]',NULL,'አዎ','ስሙዚ እና ሹገር-ፍሪ (Sugar-free) ኬኮች','[\"ምቾት\",\"የቦታው አየር\\/አቀማመጥ\",\"የምርት ጥራት\"]',NULL,'በጣም ጥሩ','ተመጣጣኝ','[\"የሜኑ ልዩነት\\/አማራጭ\"]',NULL,'አይ',NULL,NULL,'ወደ ሌላ የካልዲስ ቅርንጫፍ እሄዳለሁ',NULL,'በጣም ጠቃሚ','በጣም ጥሩ','[\"የተሻለ አቀባበል\"]',NULL,'በጣም ጥሩ','[\"ሙዚቃ\\/ድባብ\",\"ጌጥ\\/ዲኮር\"]',NULL,'አዎ አዳዲስ የጣፋጭ ምርቶች ሲኖሩ ቢነግሩን ደስ ይላል።','የሙዚቃው ድምጽ መጠነኛ ቢሆን የበለጠ ምቹ ያደርገዋል።','የጣፋጭ ምርቶች ጥራት እና ወዳጃዊ መስተንግዶ።',NULL,NULL,'2026-09-25 14:39:41'),(4,'CMC','08','በወር 1–2 ጊዜ','ቁርስ',NULL,'351–500 ብር','[\"ቁርስ\",\"ትኩስ ቡና\",\"ሻይ\"]',NULL,'የለም',NULL,'[\"አካባቢ\\/ቦታ\",\"የምርት ጥራት\",\"ዋጋ\"]',NULL,'ጥሩ','በጣም ተመጣጣኝ','[\"የአገልግሎት ፍጥነት\"]',NULL,'አይ',NULL,NULL,'ወደ ሌላ የካልዲስ ቅርንጫፍ እሄዳለሁ',NULL,'በጣም ጠቃሚ','ጥሩ','[\"ፈጣን አገልግሎት\",\"ትዕዛዝን በትክክል መውሰድ\"]',NULL,'ጥሩ','[\"የመቀመጫ ምቾት\"]',NULL,'አዎ ምርጫችንን ለማሳደግ ይጠቅማል።','የሂሳብ አከፋፈል ስርዓት በካርድና በሞባይል ፔይመንት ይበልጥ ፈጣን ቢሆን።','የቁርስ ጥራትና ትኩስ ማኪያቶ።',NULL,NULL,'2026-09-25 14:39:41'),(5,'Bole Branch','07','በሳምንት 1–2 ጊዜ','ቡና/መጠጥ',NULL,'150–250 ብር',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'በጣም ጥሩ',NULL,NULL,'በጣም ጥሩ',NULL,NULL,NULL,NULL,'የቡናው ጥራት','::1','curl/8.21.0','2026-09-25 15:07:59');
