INSERT INTO `surveys` VALUES (1,'Bole Medhanialem','04','በሳምንት 1–2 ጊዜ','ቡና/መጠጥ',NULL,'150–250 ብር','[\"\\u1275\\u12a9\\u1235 \\u1261\\u1293\",\"\\u1323\\u134b\\u132d\\/\\u12f4\\u12d8\\u122d\\u1275\"]',NULL,'አዎ','ኦት ሚልክ (Oat milk) አማራጭ ቢጨመርበት ጥሩ ነው','[\"\\u12e8\\u121d\\u122d\\u1275 \\u1325\\u122b\\u1275\",\"\\u121d\\u127e\\u1275\",\"\\u12e8\\u1265\\u122b\\u1295\\u12f1 \\u1235\\u121d\"]',NULL,'በጣም ጥሩ','ተመጣጣኝ','[\"\\u12e8\\u12a0\\u1308\\u120d\\u130d\\u120e\\u1275 \\u134d\\u1325\\u1290\\u1275\",\"\\u12e8\\u1218\\u12aa\\u1293 \\u121b\\u1246\\u121a\\u12eb\"]',NULL,'አይ',NULL,NULL,'ወደ ሌላ የካልዲስ ቅርንጫፍ እሄዳለሁ',NULL,'በጣም ጠቃሚ','በጣም ጥሩ','[\"\\u1348\\u1323\\u1295 \\u12a0\\u1308\\u120d\\u130d\\u120e\\u1275\",\"\\u1275\\u12d5\\u12db\\u12dd\\u1295 \\u1260\\u1275\\u12ad\\u12ad\\u120d \\u1218\\u12cd\\u1230\\u12f5\"]',NULL,'በጣም ጥሩ','[\"\\u12e8\\u1218\\u1240\\u1218\\u132b \\u121d\\u127e\\u1275\",\"\\u12e8\\u1265\\u122d\\u1203\\u1295 \\u12a0\\u1230\\u1323\\u1325\"]',NULL,'አዎ አዳዲስ የቁርስና የቡና አማራጮችን ቢመክሩን በጣም ይጠቅማል።','የጠረጴዛ አገልግሎት ፍጥነት በጠዋት ሰዓት ቢሻሻል መልካም ነው።','ጥሩ የቡና ጥራት እና ምቹ የመቀመጫ ድባብ ሁሌም እንድመጣ ያደርገኛል።',NULL,NULL,'2026-09-25 09:43:35','2026-09-25 09:43:35'),(2,'Kazanchis','12','በሳምንት 3 ጊዜ ወይም ከዚያ በላይ','ስብሰባ/ስራ',NULL,'351–500 ብር','[\"\\u1275\\u12a9\\u1235 \\u1261\\u1293\",\"\\u121d\\u1233\",\"\\u1240\\u12dd\\u1243\\u12db \\u1218\\u1320\\u1326\\u127d\"]',NULL,'የለም',NULL,'[\"\\u12a0\\u12ab\\u1263\\u1262\\/\\u1266\\u1273\",\"\\u12a0\\u1308\\u120d\\u130d\\u120e\\u1275\",\"\\u12e8\\u1266\\u1273\\u12cd \\u12a0\\u12e8\\u122d\\/\\u12a0\\u1240\\u121b\\u1218\\u1325\"]',NULL,'ጥሩ','መካከለኛ/ተገቢ','[\"\\u12e8\\u1230\\u122b\\u1270\\u129e\\u127d \\u12a0\\u1308\\u120d\\u130d\\u120e\\u1275\",\"\\u1295\\u133d\\u1205\\u1293\"]',NULL,'አዎ','የተሻለ አገልግሎት',NULL,'ወደ ሌላ ካፌ/የቡና ቤት እሄዳለሁ',NULL,'ጠቃሚ','ጥሩ','[\"\\u12e8\\u1270\\u123b\\u1208 \\u130d\\u1295\\u1299\\u1290\\u1275\",\"\\u12e8\\u121c\\u1291 \\u121b\\u1265\\u122b\\u122a\\u12eb\"]',NULL,'ጥሩ','[\"\\u12e8\\u1320\\u1228\\u1334\\u12db\\u1293 \\u12c8\\u1295\\u1260\\u122d \\